#!/usr/bin/env Rscript

# Reproducible TSMA tutorial analysis ---------------------------------------
#
# This script analyzes only the synthetic dataset generated by the published
# code. It never reads restricted cohort data.

source(file.path("R Code", "tsma_core.R"))

n_bootstrap <- as.integer(Sys.getenv("TSMA_BOOTSTRAPS", "50"))
if (is.na(n_bootstrap) || n_bootstrap < 10L) {
  stop("TSMA_BOOTSTRAPS must be an integer of at least 10.")
}

data_path <- file.path("Data", "synthetic_unbalanced.rds")
results_dir <- "results"
results_path <- file.path(results_dir, "tutorial_metrics.csv")
metadata_path <- file.path(results_dir, "run_metadata.txt")
representative_seed_path <- file.path(results_dir, "representative_seed.txt")

if (!file.exists(data_path)) {
  stop(
    "Synthetic data not found. Run `Rscript 'R Code/benchmark_tsma.R'` first."
  )
}
if (!file.exists(representative_seed_path)) {
  stop("Representative seed record not found. Run the benchmark first.")
}

generation_seed <- as.integer(readLines(representative_seed_path, n = 1L))
if (is.na(generation_seed)) stop("Representative seed must be an integer.")
analysis_seed <- generation_seed + 50000L

data <- readRDS(data_path)
evaluation <- evaluate_tsma_methods(
  data = data,
  analysis_seed = analysis_seed,
  n_bootstrap = n_bootstrap
)
results <- evaluation$results

dir.create(results_dir, showWarnings = FALSE, recursive = TRUE)
utils::write.csv(results, results_path, row.names = FALSE, na = "NA")

metadata <- c(
  "This analysis uses a fully synthetic dataset and no restricted cohort records.",
  sprintf("Representative generation seed: %d", generation_seed),
  "Representative seed rule: closest to median TSMA-minus-UNDER F1 and AUC-PR changes; never the maximum.",
  sprintf("Analysis seed: %d", analysis_seed),
  sprintf("Rows: %d", nrow(data)),
  sprintf("Predictors: %d", ncol(data) - 1L),
  sprintf("Observed positive prevalence: %.4f", mean(data$case_control == "1")),
  sprintf("Train rows: %d", nrow(evaluation$train_data)),
  sprintf("Test rows: %d", nrow(evaluation$test_data)),
  sprintf("Requested TSMA bootstrap models: %d", n_bootstrap),
  sprintf(
    "Successful TSMA bootstrap models: %d",
    evaluation$successful_bootstraps
  ),
  sprintf("Failed TSMA bootstrap models: %d", length(evaluation$failure_messages)),
  sprintf("R version: %s", R.version.string),
  sprintf("glmnet version: %s", as.character(utils::packageVersion("glmnet"))),
  sprintf("ROCR version: %s", as.character(utils::packageVersion("ROCR"))),
  sprintf("Synthetic data MD5: %s", unname(tools::md5sum(data_path)))
)
if (length(evaluation$failure_messages)) {
  metadata <- c(metadata, "Failure messages:", evaluation$failure_messages)
}
writeLines(metadata, metadata_path)

print_data <- results
numeric_columns <- vapply(print_data, is.numeric, logical(1))
print_data[numeric_columns] <- lapply(print_data[numeric_columns], round, digits = 4)
print(print_data, row.names = FALSE)
cat("\nResults written to", results_path, "\n")
cat("Run metadata written to", metadata_path, "\n")
